package org.novasos.healthysv2.appointment;
import java.time.Instant;import java.util.*;import jakarta.persistence.*;
@Entity @Table(name="appointment_participant",schema="appointment") class AppointmentParticipant{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="appointment_id")private Appointment appointment;@Column(name="person_id",nullable=false)private UUID personId;@Column(nullable=false,length=50)private String role;@Column(nullable=false,length=30)private String status;protected AppointmentParticipant(){}static AppointmentParticipant create(Appointment a,UUID p,String r){var x=new AppointmentParticipant();x.appointment=a;x.personId=Objects.requireNonNull(p);x.role=r.trim().toUpperCase();x.status="INVITED";return x;}void status(String value){status=value.trim().toUpperCase();}UUID getId(){return id;}UUID getPersonId(){return personId;}String getRole(){return role;}String getStatus(){return status;}}
@Entity @Table(name="appointment_status_history",schema="appointment") class AppointmentStatusHistory{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="appointment_id")private Appointment appointment;@Column(name="previous_status",length=30)private String previous;@Column(name="new_status",nullable=false,length=30)private String next;@Column(name="changed_by")private UUID changedBy;@Column(name="changed_at",nullable=false)private Instant changedAt;@Column(columnDefinition="text")private String reason;protected AppointmentStatusHistory(){}static AppointmentStatusHistory create(Appointment a,String previous,String next,UUID actor,String reason){var x=new AppointmentStatusHistory();x.appointment=a;x.previous=previous;x.next=next;x.changedBy=actor;x.changedAt=Instant.now();x.reason=reason;return x;}UUID getId(){return id;}String getPrevious(){return previous;}String getNext(){return next;}UUID getChangedBy(){return changedBy;}Instant getChangedAt(){return changedAt;}String getReason(){return reason;}}
@Entity @Table(name="waiting_queue",schema="appointment") class WaitingQueueEntry{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="appointment_id")private Appointment appointment;@Column(name="organization_id",nullable=false)private UUID organizationId;@Column(name="queue_number",nullable=false,length=50)private String number;@Column(name="checked_in_at",nullable=false)private Instant checkedInAt;@Column(name="called_at")private Instant calledAt;@Column(name="completed_at")private Instant completedAt;@Column(nullable=false,length=30)private String status;protected WaitingQueueEntry(){}static WaitingQueueEntry create(Appointment a,UUID o,String number){var x=new WaitingQueueEntry();x.appointment=a;x.organizationId=o;x.number=number;x.checkedInAt=Instant.now();x.status="WAITING";return x;}void call(){if(!"WAITING".equals(status))throw new IllegalStateException("Queue entry is not waiting");calledAt=Instant.now();status="CALLED";}void complete(){if(!Set.of("WAITING","CALLED").contains(status))throw new IllegalStateException("Queue entry is closed");completedAt=Instant.now();status="COMPLETED";}boolean isOpen(){return Set.of("WAITING","CALLED").contains(status);}UUID getId(){return id;}UUID getOrganizationId(){return organizationId;}String getNumber(){return number;}Instant getCheckedInAt(){return checkedInAt;}Instant getCalledAt(){return calledAt;}Instant getCompletedAt(){return completedAt;}String getStatus(){return status;}}
